import { z } from "zod";

export const PROFILE_LINK_TTL_MS = 24 * 60 * 60 * 1000;
const id = z.string().min(1).max(128);
const revision = z.number().int().nonnegative();
// 256 random bits, generated by the issuing browser. Never store the raw value.
export const profileLinkToken = z.string().regex(/^[A-Za-z0-9_-]{43}$/);
export const profileLinkCommand = z.discriminatedUnion("action", [
  z
    .object({
      action: z.literal("issue"),
      memberId: id,
      revision,
      key: z.string().min(1).max(128),
      token: profileLinkToken,
    })
    .strict(),
  z.object({ action: z.literal("preview"), token: profileLinkToken }).strict(),
  z
    .object({
      action: z.literal("claim"),
      token: profileLinkToken,
      password: z.string().min(1).max(256),
    })
    .strict(),
  z.object({ action: z.literal("approve"), id, revision }).strict(),
  z.object({ action: z.literal("revoke"), id, revision }).strict(),
  z.object({ action: z.literal("list") }).strict(),
]);
export const profileLinkReceipt = z
  .object({
    id,
    memberId: id,
    profileName: z.string(),
    profileRole: z.enum(["parent", "teen", "child"]),
    account: z
      .object({
        id,
        name: z.string(),
        role: z.enum(["parent", "teen", "child"]),
      })
      .strict()
      .nullable(),
    state: z.enum([
      "pending",
      "claimed",
      "linked",
      "revoked",
      "expired",
      "unavailable",
    ]),
    revision,
    expiresAt: z.string().datetime(),
  })
  .strict();
export type ProfileLinkReceipt = z.infer<typeof profileLinkReceipt>;
